// A1 shows a real program, a real compiler message, real bytes and real sizes. This test compiles and runs the
// program that the animation displays with the same toolchain learners use, and fails if anything on screen is stale.
// (Every value the course shows must be generated by running code, never typed by hand: CLAUDE.md.)
import { describe, expect, it } from 'vitest';
import { execFileSync, spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { compileWasm, runWasm } from '../shared/wasm-node';
import { ANIM_DIR } from './lib.mjs';

const ID = 'a01-press-run';
const scene = (f: string) => readFileSync(path.join(ANIM_DIR, ID, 'compositions', f), 'utf8');

const ENT: Record<string, string> = { '&lt;': '<', '&gt;': '>', '&amp;': '&', '&quot;': '"' };
/** Text of an HTML fragment with tags removed (no separators added, so code indentation survives). */
const plain = (html: string) => html.replace(/<svg[\s\S]*?<\/svg>/g, '').replace(/<[^>]+>/g, '').replace(/&(lt|gt|amp|quot);/g, m => ENT[m]);

/** The C source shown in the editor: the text of each `.pr-line`'s code span. */
function listing(html: string): string {
  const lines = [...html.matchAll(/<div class="pr-line[^"]*"[^>]*><span class="pr-ln"[^>]*>\d+<\/span><span>([\s\S]*?)<\/span><\/div>/g)].map(m => plain(m[1]).replace(/\s+$/, ''));
  return lines.join('\n') + '\n';
}

const hex = (b: Uint8Array) => [...b].map(x => x.toString(16).toUpperCase().padStart(2, '0'));

describe('A1: what the animation shows is what the toolchain does', () => {
  const source = listing(scene('pr-01-source.html'));

  it('shows the same listing in the editor of scenes 1 and 2', () => {
    expect(source.split('\n')).toHaveLength(8); // seven lines and the trailing newline
    expect(listing(scene('pr-02-compile.html'))).toBe(source);
  });

  it('compiles with exactly the compiler message on screen, and the warning does not stop the build', { timeout: 120_000 }, async () => {
    const out = await compileWasm({ files: { 'main.c': source }, sources: ['main.c'] });
    expect(out.ok).toBe(true);
    expect(out.diagnostics).toHaveLength(1);
    const d = out.diagnostics[0];
    expect(d.severity).toBe('warning');
    expect(plain(scene('pr-02-compile.html'))).toContain(`${d.file}:${d.line}:${d.col}: ${d.severity}: ${d.message} [${d.flag}]`);
    // The squiggle is drawn under "unused" on line 4, at the reported column.
    expect(source.split('\n')[d.line - 1].indexOf('unused') + 1).toBe(d.col);
  });

  it('stops the build on an error ("an error stops the build")', { timeout: 120_000 }, async () => {
    const out = await compileWasm({ files: { 'main.c': 'int main(void) { int x = ; return x; }\n' }, sources: ['main.c'] });
    expect(out.ok).toBe(false);
    expect(out.wasm).toBeUndefined();
    expect(out.diagnostics.some(d => d.severity === 'error')).toBe(true);
  });

  it('produces a main.wasm with the header bytes and size on screen, and prints the bytes on screen', { timeout: 120_000 }, async () => {
    const out = await compileWasm({ files: { 'main.c': source }, sources: ['main.c'] });
    const wasm = out.wasm!;
    // Scene 3: the first eight bytes (\0asm and version 1) and the size.
    const link = scene('pr-03-link.html');
    const shown = [...link.matchAll(/<span class="pr03-byte">([0-9A-F]{2})<\/span>/g)].map(m => m[1]);
    expect(shown).toEqual(hex(wasm.slice(0, 8)));
    expect(shown).toEqual(['00', '61', '73', '6D', '01', '00', '00', '00']);
    expect(plain(link)).toContain(`${Math.round(wasm.length / 1000)} KB`);

    // Scenes 4 and 5: the program prints Hello, C! and a newline: ten bytes.
    const run = await runWasm(wasm);
    expect(run.stdout).toBe('Hello, C!\n');
    const bytes = Buffer.from(run.stdout);
    expect(bytes).toHaveLength(10);
    const s4 = scene('pr-04-run.html');
    expect(plain(s4)).toContain('printf("Hello, C!\\n");');
    expect(plain(s4)).toContain(`${bytes.length} bytes`);
    const s5 = scene('pr-05-output.html');
    expect([...s5.matchAll(/<div class="pr05-b">([0-9A-F]{2})<\/div>/g)].map(m => m[1])).toEqual(hex(bytes));
    expect(plain(s5)).toContain(`${bytes.length} bytes arrive on file descriptor 1`);
    const typed = [...s5.matchAll(/<span class="pr05-ch">([^<]*)<\/span>/g)].map(m => m[1]).join('');
    expect(typed + '\n').toBe(run.stdout);
  });

  it('shows pointer sizes of 4 bytes in wasm32 and 8 bytes natively', { timeout: 120_000 }, async () => {
    const ptr = '#include <stdio.h>\nint main(void) { printf("%zu\\n", sizeof(void *)); return 0; }\n';
    const out = await compileWasm({ files: { 'main.c': ptr }, sources: ['main.c'] });
    const wasmSize = Number((await runWasm(out.wasm!)).stdout.trim());
    const native = spawnSync('gcc', ['--version']).status === 0;
    let nativeSize = 8; // x86-64 and arm64 are both LP64 with 64-bit pointers; verified below when gcc is present
    if (native) {
      const dir = mkdtempSync(path.join(tmpdir(), 'a01-ptr-'));
      try {
        writeFileSync(path.join(dir, 'ptr.c'), ptr);
        execFileSync('gcc', ['-std=c17', '-Wall', '-Wextra', '-pedantic', path.join(dir, 'ptr.c'), '-o', path.join(dir, 'ptr')]);
        nativeSize = Number(execFileSync(path.join(dir, 'ptr'), { encoding: 'utf8' }).trim());
      } finally {
        rmSync(dir, { recursive: true, force: true });
      }
    }
    const s6 = plain(scene('pr-06-native.html'));
    expect(s6).toContain(`a pointer is ${wasmSize} bytes`);
    expect(s6).toContain(`a pointer is ${nativeSize} bytes`);
    expect([wasmSize, nativeSize]).toEqual([4, 8]);
  });
});
